     1→import { NextResponse } from 'next/server';
     2→import { getServerSession } from 'next-auth';
     3→import { authOptions } from '@/lib/auth';
     4→import { prisma } from '@/lib/prisma';
     5→
     6→export async function GET(request: Request) {
     7→  try {
     8→    const session = await getServerSession(authOptions);
     9→    if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    10→
    11→    const { searchParams } = new URL(request.url);
    12→    const testType = searchParams.get('testType') || 'PLACEMENT';
    13→
    14→    const allQuestions = await prisma.placementQuestion.findMany({
    15→      where: { testType }
    16→    });
    17→    const shuffled = allQuestions.sort(() => 0.5 - Math.random());
    18→    const selected = shuffled.slice(0, 20);
    19→
    20→    return NextResponse.json(selected);
    21→  } catch (error) {
    22→    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    23→  }
    24→}
    25→
    26→export async function POST(request: Request) {
    27→  try {
    28→    const session = await getServerSession(authOptions);
    29→    if (!session) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    30→
    31→    const body = await request.json();
    32→    const { answers, testType = 'PLACEMENT' } = body;
    33→    let score = 0;
    34→    const details = [];
    35→
    36→    const questions = await prisma.placementQuestion.findMany({
    37→      where: { id: { in: Object.keys(answers) } }
    38→    });
    39→
    40→    for (const q of questions) {
    41→      const isCorrect = answers[q.id] === q.correctAnswer;
    42→      if (isCorrect) score++;
    43→      details.push({ questionId: q.id, answer: answers[q.id], correct: isCorrect });
    44→    }
    45→
    46→    const percentage = questions.length > 0 ? (score / questions.length) * 100 : 0;
    47→    let level = 'A1';
    48→    if (percentage >= 90) level = 'C1';
    49→    else if (percentage >= 75) level = 'B2';
    50→    else if (percentage >= 60) level = 'B1';
    51→    else if (percentage >= 40) level = 'A2';
    52→
    53→    const attempt = await prisma.placementTestAttempt.create({
    54→      data: {
    55→        studentId: session.user.id,
    56→        testType,
